/**
 * Every round the client knows, by the int compact descriptor a replay carries.
 *
 * Kept apart from `loadout-catalogue.ts` for one reason: there are 4019 of them
 * across eleven nations, and nothing in a browser ever needs this table. A
 * replay's loadout is resolved where the replay is decoded, on the server, and
 * what reaches the page is already named. Importing this from a client
 * component would put a quarter of a megabyte of shell names into the bundle to
 * answer a question the server has already answered.
 *
 * Keyed on the whole int compact descriptor rather than on (nation, id) because
 * that is what the `shellsSetups` property holds, and because a shell's id is
 * only unique inside its nation: `(id << 8) + 10 + (nationID << 4)`, where 10
 * is `ITEM_TYPE.shell`.
 *
 * Each entry is `[name, kind, premium]`, a tuple rather than an object to keep
 * the file a quarter of the size it would otherwise be.
 *
 *  - `name` is the client's own, scoped to its nation, which is what the mod
 *    sends and the page labels a round with;
 *  - `kind` is one of `ARMOR_PIERCING`, `ARMOR_PIERCING_CR`, `HIGH_EXPLOSIVE`, `HOLLOW_CHARGE`, `SMOKE`,
 *    and it is what picks the round's icon;
 *  - `premium` is whether the round costs gold, taken from the `<icon>` field
 *    rather than from the price. The client itself decides this from the SHOP
 *    (`isPremium` is `buyPrices.hasPriceIn(GOLD)` in `fitting_item.py`), which
 *    a replay cannot see; but the definitions carry a separate icon for the
 *    gold round of every gun (`ap_premium`, `ap_cr_premium`, `hc_premium`,
 *    `he_modern_premium`, and their `_tray` variants), so the icon is the
 *    static half of the same fact. Worth stating because the obvious guess is
 *    wrong: APCR is NOT premium by itself -- the M60's standard round is APCR
 *    with the plain `ap_cr` icon, and its gold round is the HEAT.
 *
 * Read out of `item_defs/vehicles/<nation>/components/shells.xml`, after the
 * `<icons>` block, where each child is a round whose element name is its name.
 * Checked before being trusted: the three rounds of one real Onslaught battle
 * resolved to `_105mm_APCR_M68M2` (not premium), `_105mm_HEAT-T_T384E4`
 * (premium) and `_105mm_HE_M68M2` (not premium), all three on the M60's M68 gun.
 *
 * Generated. Regenerate from the client sources rather than editing by hand.
 */

/** `[name, kind, premium]`, as packed above. */
export type ShellEntry = readonly [string, string, 0 | 1];

